custom_css:
:root {
  --xal-void: #07050c;
  --xal-ink: #0b0812;
  --xal-panel: rgba(10, 7, 16, 0.88);
  --xal-panel-deep: rgba(8, 6, 14, 0.94);
  --xal-gold: #c4a25a;
  --xal-gold-bright: #e8d4a0;
  --xal-gold-dim: rgba(196, 162, 90, 0.55);
  --xal-gold-hair: rgba(196, 162, 90, 0.28);
  --xal-lilac: #b48cff;
  --xal-lilac-dim: rgba(160, 120, 210, 0.28);
  --xal-ice: #7ec8ff;
  --xal-cream: #efe6d4;
}

body, #sheld, #chat, #send_textarea, .mes_text, .drawer-content {
  font-family: "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
}

/* Deeper void shell; keep ST chrome visible */
#sheld {
  background: var(--xal-panel-deep) !important;
  border: 1px solid var(--xal-gold-dim) !important;
  box-shadow:
    0 0 0 1px rgba(10, 7, 16, 0.9),
    inset 0 0 48px rgba(70, 28, 110, 0.16),
    0 0 28px rgba(0, 0, 0, 0.35) !important;
}

#form_sheld, #chat, #send_form {
  border-color: var(--xal-gold-dim) !important;
}

#send_form {
  background: rgba(8, 6, 14, 0.78) !important;
  border: 1px solid var(--xal-gold-dim) !important;
  box-shadow:
    inset 0 0 22px rgba(70, 28, 110, 0.14),
    0 0 0 1px rgba(10, 7, 16, 0.7) !important;
}

#send_but, #send_form {
  border-color: var(--xal-gold-dim) !important;
}

#send_textarea {
  background: rgba(8, 6, 14, 0.82) !important;
  color: var(--xal-cream) !important;
  border: 1px solid var(--xal-gold-dim) !important;
  box-shadow: inset 0 0 16px rgba(40, 16, 64, 0.22);
}

#send_textarea:focus {
  border-color: var(--xal-gold) !important;
  outline: none;
}

/* Drawers / nav */
.drawer-content, .inline-drawer-content,
#right-nav-panel, #left-nav-panel,
#rm_print_characters_block, #rm_ch_create_block,
#WorldInfo, #wi-details {
  background: var(--xal-panel) !important;
  border-color: var(--xal-gold-dim) !important;
  box-shadow:
    0 0 28px rgba(70, 24, 110, 0.16),
    inset 0 0 36px rgba(70, 28, 110, 0.12);
}

.inline-drawer-header, .drawer-header,
.standoutHeader {
  border-bottom: 1px solid var(--xal-gold-hair) !important;
  background: rgba(12, 8, 20, 0.7) !important;
}

/* Top bar darker */
#top-bar, #top-settings-holder, #top-settings-holder .drawer-icon {
  background: rgba(6, 4, 10, 0.82) !important;
}
#top-bar {
  border-bottom: 1px solid var(--xal-gold-hair) !important;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.35);
}

/* Buttons: gold hover, no neon */
.menu_button, .menu_button_icon, .menu_button.menu_button_icon,
#send_but, .qr--button {
  border: 1px solid var(--xal-gold-dim) !important;
  background: rgba(18, 12, 28, 0.78) !important;
  color: var(--xal-cream) !important;
  border-radius: 3px !important;
  box-shadow: inset 0 0 10px rgba(70, 28, 110, 0.1);
}
.menu_button:hover, .menu_button_icon:hover,
#send_but:hover, .qr--button:hover {
  border-color: var(--xal-gold) !important;
  background: rgba(196, 162, 90, 0.18) !important;
  color: var(--xal-gold-bright) !important;
  box-shadow: 0 0 10px rgba(180, 140, 80, 0.18);
}

/* Chat bubbles: more ink; user gold inset, bot lilac inset */
#chat {
  background: rgba(7, 5, 12, 0.35) !important;
}
.mes {
  border-radius: 5px;
  background: rgba(10, 8, 16, 0.55);
}
.mes .mes_text {
  line-height: 1.58;
  color: var(--xal-cream);
}
.mes[is_user="true"] {
  background: rgba(22, 16, 28, 0.62);
  box-shadow:
    inset 0 0 0 1px rgba(196, 162, 90, 0.28),
    inset 0 0 22px rgba(90, 60, 20, 0.08);
}
.mes:not([is_user="true"]) {
  background: rgba(12, 8, 20, 0.58);
  box-shadow:
    inset 0 0 0 1px rgba(160, 120, 210, 0.24),
    inset 0 0 24px rgba(70, 30, 110, 0.12);
}

q, .mes_text q {
  color: #c9b0ff !important;
}

.character_name, .ch_name, .name_text {
  color: #f0e2b8 !important;
}

/* Scrollbar gold-purple */
* {
  scrollbar-width: thin;
  scrollbar-color: #c4a25a #0a0710;
}
::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-track { background: #0a0710; }
::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #4a2e6e, #c4a25a);
  border-radius: 8px;
  border: 1px solid #1a1224;
}
::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, #c4a25a, #6a4488);
}

#rm_print_characters_block .character_select,
.avatar img, .avatar {
  border: 1px solid var(--xal-gold-dim) !important;
}

.toastr {
  background: rgba(10, 7, 16, 0.94) !important;
  border: 1px solid var(--xal-gold-dim) !important;
  color: var(--xal-cream) !important;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
}

.text_pole, select, input[type="text"], input[type="number"], textarea {
  background: rgba(8, 6, 14, 0.72) !important;
  border-color: var(--xal-gold-hair) !important;
  color: var(--xal-cream) !important;
}

.world_entry, .wi-card, .world_entry_thin_v2 {
  border-color: var(--xal-gold-hair) !important;
  background: rgba(12, 8, 18, 0.7) !important;
}

#extensionsMenu, .list-group {
  background: rgba(10, 7, 16, 0.94) !important;
  border-color: var(--xal-gold-dim) !important;
}
#extensionsMenu .list-group-item:hover,
#xal-wand:hover {
  background: rgba(196, 162, 90, 0.12) !important;
  color: var(--xal-gold-bright);
}

#xal-hud, .xal-hud, [id*="xal"] {
  border-color: var(--xal-gold) !important;
}

/* Do not hide send / wand / options chrome */
#leftSendForm, #rightSendForm, #extensionsMenuButton,
#options_button, #send_but, #mes_stop, #qr--bar {
  visibility: visible !important;
}
